#!/bin/bash
set -eo pipefail
sequence=26
root=/data1/home/sunyiq/kalmannet_hamid_weights_20260923_v1
date -u '+SNAPSHOT_UTC=%Y-%m-%dT%H:%M:%SZ'
one_step=$(sacct -X -j 227625 -n -P --format=State | sort -u | tr -d '[:space:]|')
test "$one_step" = "COMPLETED"
printf '\nOWN_JOBS_BEFORE_SUBMISSION\n'
squeue -u sunyiq -h -o '%i|%j|%T|%P|%R'
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY'
import base64, hashlib, io, json, shutil, tarfile
from pathlib import Path
root = Path('/data1/home/sunyiq/kalmannet_hamid_weights_20260923_v1')
base = root / 'formal_package_v2'
dest = root / 'formal_package_v3'
out = root / 'formal_attempt_003'
claim = root / 'formal_attempt_003_submission_claim'
assert base.is_dir() and not dest.exists() and not out.exists() and not claim.exists()
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
assert sha(base / 'manifest.json') == 'b4a2f2b7d68ff131776639f1d9998fbbdd2609f8c89b85958832f365e35a317e'
assert sha(base / 'protocol.json') == '2c070638bd6c25d672ad42a85fdb8cf234b0132e31e5399b8e7339f3fdc417db'
assert sha(root / 'formal_attempt_002' / 'HALT.json') == '42e23aba58d177c2e1a58cc03a4e2ef49dc38d91e4427e600292a340a2883557'
raw = base64.b64decode('')
assert hashlib.sha256(raw).hexdigest() == 'cf0c3bcf41498d48982b4c4534370769332314baf07b8a5c9db319852b427abf'
with tarfile.open(fileobj=io.BytesIO(raw), mode='r:gz') as archive:
    members = archive.getmembers()
    expected = ['configs/objective-current-0-highflow-1-seed-42.json', 'configs/objective-current-0-highflow-1-seed-43.json', 'configs/objective-current-0-highflow-1-seed-44.json', 'configs/objective-current-0-highflow-2-seed-42.json', 'configs/objective-current-0-highflow-2-seed-43.json', 'configs/objective-current-0-highflow-2-seed-44.json', 'configs/objective-current-0p05-highflow-1-seed-42.json', 'configs/objective-current-0p05-highflow-1-seed-43.json', 'configs/objective-current-0p05-highflow-1-seed-44.json', 'configs/objective-current-0p05-highflow-2-seed-42.json', 'configs/objective-current-0p05-highflow-2-seed-43.json', 'configs/objective-current-0p05-highflow-2-seed-44.json', 'protocol.json', 'train_weights.py', 'train_weights.slurm', 'manifest.json']
    assert sorted(m.name for m in members) == sorted(expected)
    assert all(m.isfile() and not m.name.startswith('/') and '..' not in Path(m.name).parts for m in members)
    shutil.copytree(base, dest)
    for member in members:
        target = dest / member.name
        assert target.is_file()
        target.write_bytes(archive.extractfile(member).read())
assert sha(dest / 'manifest.json') == '4bd8fe167bb5d6932a25161e9855bfdf03f656352b567aeee903e31925b6899f'
assert sha(dest / 'protocol.json') == '2575b0fcdafcf5befb38c4e6a431f856a202164c81763a3eb99e1c141d6055cc'
old = json.loads((base / 'manifest.json').read_text())['files']
new = json.loads((dest / 'manifest.json').read_text())['files']
assert old.keys() == new.keys()
for name, want in new.items():
    assert sha(dest / name) == want, name
    if name.startswith(('sources/', 'initial_states/', 'initial_weights/')):
        assert sha(base / name) == want, name
protocol = json.loads((dest / 'protocol.json').read_text())
assert len(protocol['cells']) == 12
assert protocol['cells'] == json.loads((base / 'protocol.json').read_text())['cells']
assert protocol['data'] == json.loads((base / 'protocol.json').read_text())['data']
assert protocol['frozen_initial_weights'] == json.loads((base / 'protocol.json').read_text())['frozen_initial_weights']
out.mkdir()
(out / 'logs').mkdir()
(out / 'tmp').mkdir()
(out / 'runs').mkdir()
with (out / 'deployment.json').open('x') as f:
    json.dump({'state':'ELEVEN_CELLS_DEPLOYMENT_VERIFIED','base_manifest_sha256':sha(base / 'manifest.json'),'manifest_sha256':sha(dest / 'manifest.json'),'old_failure_preserved':True,'cells_to_run':list(range(1,12))}, f, indent=2)
print(json.dumps(json.loads((out / 'deployment.json').read_text())))
PY
bash -n "$root/formal_package_v3/train_weights.slurm"
mkdir "$root/formal_attempt_003_submission_claim"
set +e
submission_output=$(sbatch "$root/formal_package_v3/train_weights.slurm" 2>&1)
submission_exit=$?
set -e
printf '%s\n' "$submission_output" | tee "$root/formal_attempt_003_submission_claim/sbatch_output.txt"
printf '%s\n' "$submission_exit" > "$root/formal_attempt_003_submission_claim/sbatch_exit.txt"
job_id=$(printf '%s\n' "$submission_output" | sed -n 's/^Submitted batch job \([0-9][0-9]*\)$/\1/p')
if [ "$submission_exit" -ne 0 ] || ! [[ "$job_id" =~ ^[0-9]+$ ]]; then
 printf '%s\n' 'SUBMISSION_NOT_CONFIRMED_DO_NOT_RESUBMIT'
 exit 41
fi
printf '%s\n' "$job_id" > "$root/formal_attempt_003_submission_claim/job_id.txt"
printf 'REMAINING_CELLS_SUBMITTED_JOB_ID=%s\n' "$job_id"
squeue -h -j "$job_id" -o '%i|%j|%T|%R' || true
printf '\nOWN_JOBS_AFTER_SUBMISSION\n'
squeue -u sunyiq -h -o '%i|%j|%T|%P|%R'
printf '\nISOLATED_REMAINING_CELLS_SUBMISSION_COMPLETE\n'
